package com.ruoyi.medical.persistence;
import com.ruoyi.medical.workflow.*;
import io.temporal.api.workflowservice.v1.*;
import io.temporal.common.converter.DefaultDataConverter;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static com.ruoyi.medical.persistence.TaskRunBootstrapSchemaTest.id;

/** Authored for the deferred test phase. No runtime/provider integration is implied. */
class TaskRunSourceVerifierProtocolBindingTest {
    TaskRunWorkflowProtocolBindingTest f;
    @BeforeEach void setup()throws Exception{f=new TaskRunWorkflowProtocolBindingTest();f.setup();}
    @AfterEach void cleanup(){f.cleanup();}
    SectionWriterWorkflowExtensionV1 writer(String revision){return new SectionWriterWorkflowExtensionV1("1.0.0",revision,f.deployment.canonicalSha256(),"isolated-writer-v1","medical.task.section-writer.execute.v1","medical.run.section-writer.prepare.v1","medical.run.section-writer.inventory.v1","medical.run.section-writer.dispatch.v1","medical.run.section-writer.commit.v1","medical.run.section-writer.recover.v1",SectionWriterWorkflowExtensionV1.MARKER);}
    SourceVerifierWorkflowExtensionV1 extension(String revision){return new SourceVerifierWorkflowExtensionV1("1.0.0",revision,f.deployment.canonicalSha256(),writer(id(97)).canonicalSha256(),"isolated-verifier-v1","medical.task.source-verifier.execute.v1","medical.run.source-verifier.prepare.v1","medical.run.source-verifier.inventory.v1","medical.run.source-verifier.dispatch.v1","medical.run.source-verifier.commit.v1","medical.run.source-verifier.recover.v1",SourceVerifierWorkflowExtensionV1.MARKER);}
    TaskRunWorkflowLedger.Intent prepare()throws Exception{var i=f.launches.prepare(f.f.start,f.f.registered,f.f.config);f.bindings.prepare(f.f.start,i,f.deployment,writer(id(97)),extension(id(98)));return i;}
    void sdk(TaskRunWorkflowLedger.Intent i,SourceVerifierWorkflowExtensionV1 extension){f.sdk(i,i.commandId());var response=f.rpc.getWorkflowExecutionHistory(GetWorkflowExecutionHistoryRequest.getDefaultInstance());var history=response.getHistory().toBuilder();var event=history.getEvents(0).toBuilder();var start=event.getWorkflowExecutionStartedEventAttributes().toBuilder();var memo=start.getMemo().toBuilder();writer(id(97)).memo().forEach((k,v)->memo.putFields(k,DefaultDataConverter.STANDARD_INSTANCE.toPayload(v).orElseThrow()));extension.memo().forEach((k,v)->memo.putFields(k,DefaultDataConverter.STANDARD_INSTANCE.toPayload(v).orElseThrow()));start.setMemo(memo);event.setWorkflowExecutionStartedEventAttributes(start);history.setEvents(0,event);when(f.rpc.getWorkflowExecutionHistory(any(GetWorkflowExecutionHistoryRequest.class))).thenReturn(response.toBuilder().setHistory(history).build());}
    @Test void cannotUpgradePriorBaseAttempt()throws Exception{var i=f.prepare();f.launches.attempt(f.f.start,i);assertThrows(TenantAccessException.class,()->f.bindings.prepare(f.f.start,i,f.deployment,writer(id(97)),extension(id(98))));assertEquals(1,f.db.operations.size());}
    @Test void cannotUpgradePriorWriterAttempt()throws Exception{var i=f.launches.prepare(f.f.start,f.f.registered,f.f.config);f.bindings.prepare(f.f.start,i,f.deployment,writer(id(97)));f.launches.attempt(f.f.start,i);assertThrows(TenantAccessException.class,()->f.bindings.prepare(f.f.start,i,f.deployment,writer(id(97)),extension(id(98))));assertEquals(2,f.db.operations.size());}
    @Test void writerOnlyHistoryCannotCreateVerifierAcceptance()throws Exception{var i=prepare();f.launches.attempt(f.f.start,i);var permit=f.bindings.authorizeRecovery(f.a,f.f.recovery);sdk(i,extension(id(98)));var response=f.rpc.getWorkflowExecutionHistory(GetWorkflowExecutionHistoryRequest.getDefaultInstance());var history=response.getHistory().toBuilder();var event=history.getEvents(0).toBuilder();var start=event.getWorkflowExecutionStartedEventAttributes().toBuilder();start.setMemo(start.getMemo().toBuilder().removeFields(SourceVerifierWorkflowExtensionV1.CONFIG_MEMO).removeFields(SourceVerifierWorkflowExtensionV1.HASH_MEMO));event.setWorkflowExecutionStartedEventAttributes(start);history.setEvents(0,event);when(f.rpc.getWorkflowExecutionHistory(any(GetWorkflowExecutionHistoryRequest.class))).thenReturn(response.toBuilder().setHistory(history).build());f.commit();assertThrows(IllegalArgumentException.class,()->f.delivery.recover(permit));assertTrue(f.f.sql.receipts.isEmpty());}
    @Test void originalExtensionCannotBeReplacedOrRemoved()throws Exception{var i=prepare();assertThrows(TenantAccessException.class,()->f.bindings.prepare(f.f.start,i,f.deployment,writer(id(97)),extension(id(99))));assertThrows(TenantAccessException.class,()->f.bindings.prepare(f.f.start,i,f.deployment,writer(id(97)),null));assertEquals(3,f.db.operations.size());}
    @Test void baseOnlyHistoryCannotCreateVerifierAcceptance()throws Exception{var i=prepare();f.launches.attempt(f.f.start,i);var permit=f.bindings.authorizeRecovery(f.a,f.f.recovery);f.sdk(i,i.commandId());f.commit();assertThrows(IllegalArgumentException.class,()->f.delivery.recover(permit));assertTrue(f.f.sql.receipts.isEmpty());}
    @Test void recoveryUsesStoredExtensionAndActualSdkEvidence()throws Exception{var i=prepare();f.launches.attempt(f.f.start,i);var permit=f.bindings.authorizeRecovery(f.a,f.f.recovery);sdk(i,extension(id(98)));f.commit();var received=f.delivery.recover(permit);f.begin();f.bindings.record(f.a,f.f.recovery,received);var accepted=f.bindings.verifiers().requireAccepted(f.a,id(3));accepted.requireUnchanged();assertEquals(extension(id(98)),accepted.extension());assertEquals(id(90),accepted.temporalRunId());assertEquals(6,f.db.operations.size());verify(f.client,never()).newWorkflowStub(eq(TaskWorkflow.class),any(io.temporal.client.WorkflowOptions.class));}
    @Test void oldBaseLaunchRejectsUnboundExtensionMemo()throws Exception{var i=f.prepare();f.launches.attempt(f.f.start,i);var permit=f.bindings.authorizeRecovery(f.a,f.f.recovery);sdk(i,extension(id(98)));f.commit();assertThrows(IllegalArgumentException.class,()->f.delivery.recover(permit));}
    @Test void writerLaunchRejectsUnboundVerifierMemo()throws Exception{var i=f.launches.prepare(f.f.start,f.f.registered,f.f.config);f.bindings.prepare(f.f.start,i,f.deployment,writer(id(97)));f.launches.attempt(f.f.start,i);var permit=f.bindings.authorizeRecovery(f.a,f.f.recovery);sdk(i,extension(id(98)));f.commit();assertThrows(IllegalArgumentException.class,()->f.delivery.recover(permit));}
    @Test void verifierBindingAloneDoesNotAuthorizeStage()throws Exception{prepare();assertThrows(TenantAccessException.class,()->f.bindings.verifiers().requireAccepted(f.a,id(3)));verifyNoInteractions(f.rpc);}
    @Test void verifierAcceptanceIsPrivateAndTransactionBound()throws Exception{var i=prepare();f.launches.attempt(f.f.start,i);var permit=f.bindings.authorizeRecovery(f.a,f.f.recovery);sdk(i,extension(id(98)));f.commit();var received=f.delivery.recover(permit);f.begin();f.bindings.record(f.a,f.f.recovery,received);var accepted=f.bindings.verifiers().requireAccepted(f.a,id(3));for(var constructor:accepted.getClass().getDeclaredConstructors())assertTrue(java.lang.reflect.Modifier.isPrivate(constructor.getModifiers()));for(var sync:org.springframework.transaction.support.TransactionSynchronizationManager.getSynchronizations())sync.afterCompletion(0);assertThrows(TenantAccessException.class,accepted::requireUnchanged);}
    @Test void changedVerifierAuditInvalidatesAcceptance()throws Exception{var i=prepare();f.launches.attempt(f.f.start,i);var permit=f.bindings.authorizeRecovery(f.a,f.f.recovery);sdk(i,extension(id(98)));f.commit();var received=f.delivery.recover(permit);f.begin();f.bindings.record(f.a,f.f.recovery,received);var accepted=f.bindings.verifiers().requireAccepted(f.a,id(3));f.db.audits.values().stream().filter(r->"task.run.verifier.accepted.v1".equals(r.get("action"))).findFirst().orElseThrow().put("request_id",id(99));assertThrows(TenantAccessException.class,accepted::requireUnchanged);}
    @Test void changedVerifierMemoHashCannotCreateAcceptance()throws Exception{var i=prepare();f.launches.attempt(f.f.start,i);var permit=f.bindings.authorizeRecovery(f.a,f.f.recovery);sdk(i,extension(id(98)));var response=f.rpc.getWorkflowExecutionHistory(GetWorkflowExecutionHistoryRequest.getDefaultInstance());var history=response.getHistory().toBuilder();var event=history.getEvents(0).toBuilder();var start=event.getWorkflowExecutionStartedEventAttributes().toBuilder();start.setMemo(start.getMemo().toBuilder().putFields(SourceVerifierWorkflowExtensionV1.HASH_MEMO,DefaultDataConverter.STANDARD_INSTANCE.toPayload("0".repeat(64)).orElseThrow()));event.setWorkflowExecutionStartedEventAttributes(start);history.setEvents(0,event);when(f.rpc.getWorkflowExecutionHistory(any(GetWorkflowExecutionHistoryRequest.class))).thenReturn(response.toBuilder().setHistory(history).build());f.commit();assertThrows(IllegalArgumentException.class,()->f.delivery.recover(permit));assertTrue(f.f.sql.receipts.isEmpty());}
    @Test void extensionActivationIsExplicitDefaultOff(){var condition=TaskRunSourceVerifierWorkflowConfiguration.class.getAnnotation(org.springframework.boot.autoconfigure.condition.ConditionalOnProperty.class);assertFalse(condition.matchIfMissing());assertTrue(java.util.List.of(condition.name()).contains("medical.task-run.source-verifier-v1.enabled"));}
}
